import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据结构","link":"/api/SIMD-API/basic_api/data_structures/data_structures"},{"text":"GlobalTensor","link":"/api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor"},{"text":"GlobalTensor简介","link":"/api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.md","filePath":"api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.md","lastUpdated":1785832713000}'),c={name:"api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.md"};function e(o,s,t,i,r,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>GlobalTensor简介<span id="ZH-CN_TOPIC_0000002132084952"></span></h1><p>GlobalTensor用来存放Global Memory（外部存储）的全局数据。</p><p>GlobalTensor public成员函数如下。类型T支持基础数据类型以及<a href="../../aux_data_structures/TensorTrait/TensorTrait.html">TensorTrait</a>类型，但需要遵循使用此GlobalTensor的指令的数据类型支持情况。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">GlobalTensor</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="k">public</span><span class="w"> </span><span class="n">BaseGlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="c1">// PrimT用于在T传入为TensorTrait类型时萃取TensorTrait中的LiteType基础数据类型</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">PrimType</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 构造函数</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">()</span><span class="w"> </span><span class="p">{}</span>
<span class="w">    </span><span class="c1">// 初始化GlobalTensor</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">PrimType</span><span class="o">*</span><span class="w"> </span><span class="n">buffer</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">);</span><span class="w"> </span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">PrimType</span><span class="o">*</span><span class="w"> </span><span class="n">buffer</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 获取全局数据的地址 </span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">PrimType</span><span class="o">*</span><span class="w"> </span><span class="n">GetPhyAddr</span><span class="p">()</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">PrimType</span><span class="o">*</span><span class="w"> </span><span class="n">GetPhyAddr</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 获取GlobalTensor的相应偏移位置的值</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">__inout_pipe__</span><span class="p">(</span><span class="n">S</span><span class="p">)</span><span class="w"> </span><span class="n">PrimType</span><span class="w"> </span><span class="n">GetValue</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span><span class="w"> </span><span class="k">const</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="c1">// 获取某个索引位置的元素的引用</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">__inout_pipe__</span><span class="p">(</span><span class="n">S</span><span class="p">)</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">PrimType</span><span class="o">&amp;</span><span class="w"> </span><span class="k">operator</span><span class="p">()(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 设置GlobalTensor相应偏移位置的值</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetValue</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">PrimType</span><span class="w"> </span><span class="n">value</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 获取GlobalTensor的元素个数</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">GetSize</span><span class="p">()</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 返回指定偏移量的GlobalTensor</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="w"> </span><span class="k">operator</span><span class="p">[](</span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span><span class="w"> </span><span class="k">const</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="c1">// 设置GlobalTensor的shape信息</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetShapeInfo</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ShapeInfo</span><span class="o">&amp;</span><span class="w"> </span><span class="n">shapeInfo</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 获取GlobalTensor的shape信息</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">ShapeInfo</span><span class="w"> </span><span class="n">GetShapeInfo</span><span class="p">()</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 设置GlobalTensor写入L2 Cache的模式</span>
<span class="w">    </span><span class="k">template</span><span class="o">&lt;</span><span class="n">CacheRwMode</span><span class="w"> </span><span class="n">rwMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CacheRwMode</span><span class="o">::</span><span class="n">RW</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetL2CacheHint</span><span class="p">(</span><span class="n">CacheMode</span><span class="w"> </span><span class="n">mode</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 将当前GlobalTensor重解释为用户指定的新类型</span>
<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">CAST_T</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">CAST_T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">ReinterpretCast</span><span class="p">()</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">};</span>
</code></pre></div></article></div>`,1)])])}const k=a(c,[["render",e]]);export{T as __pageData,k as default};
